    explanation: "Among the major signs of the Hour is the emergence of the Beast (Dabbatul-Ard) from the earth. The Qur'an mentions it in Surah An-Naml: \"And when the Word befalls them, We will bring forth for them a creature from the earth speaking to them that the people were not certain of Our signs.\" This Beast will appear when iman has weakened and knowledge has diminished. It will carry the staff of Musa and the ring of Sulayman, and it will mark people — believers on the forehead, disbelievers on the nose. The mark will be visible to all, and there will be no hiding one's true state. Some scholars say it will speak, declaring to people that they did not have certainty in Allah's signs. This is not a parable. The Beast is real, physical, and part of the sequence of events leading to the Last Hour. It signifies a time when the test of this world is ending, and identities are being finalized. What side will you be on?",
