    translation: "Ya'juj and Ma'juj — The Hordes Behind the Barrier",
    explanation: "The Prophet ﷺ spoke of Ya'juj and Ma'juj (Gog and Magog), two massive groups of people currently trapped behind a barrier built by Dhul-Qarnayn, as mentioned in the Qur'an. They are descendants of Adam, enormous in number, and corrupt in nature. The Prophet ﷺ said they scratch at the barrier every day, almost breaking through, but Allah restores it each night. Near the end of time, after the descent of Isa (AS) and the death of the Dajjal, Allah will release them. They will pour out in waves, drinking rivers dry, destroying everything in their path. The believers will take refuge, and Isa (AS) will make du'a. Allah will send a disease or plague to destroy them all in one night. Their bodies will cover the earth, and Allah will send birds to carry the carcasses away. This is not myth — it is prophecy. The barrier exists. The hordes are real. And their release is one of the final signs before the Last Hour. Let this remind you: Allah's plan is unfolding. The end is scripted. Are you ready?",
