    transliteration: "Allāhumma innī aʿūdhu bika min ʿadhābil-qabri wa aʿūdhu bika min fitnatil-Masīḥid-Dajjāl wa aʿūdhu bika min fitnatil-maḥyā wal-mamāt",
    translation: "\"O Allah, I seek refuge in You from the punishment of the grave, from the trial of the Dajjal, and from the trials of life and death.\"",
