    explanation: "One of the greatest signs of the Hour is the return of Prophet Isa (Jesus), son of Maryam (AS). The Prophet Muhammad ﷺ said Isa will descend near a white minaret in Damascus, resting his hands on the wings of two angels. He will descend during Fajr prayer, and the Muslims will recognize him. He will pray behind the Mahdi, affirming that this Ummah follows Muhammad ﷺ. Then he will pursue and kill the Dajjal at the gate of Ludd (in Palestine). After that, Isa (AS) will live among the Muslims, rule with justice, break the cross, kill the swine, abolish the jizyah, and establish the truth of Islam. He will marry, have children, and live for 40 years before passing away and being buried next to the Prophet ﷺ in Madinah. This is not symbolism. Isa (AS) did not die — Allah raised him alive to the heavens, and he will return. His return will unite the believers, destroy falsehood, and usher in a brief era of peace before the final trials. Are you preparing to be among those who meet him?",
